import { execFileSync } from "node:child_process";
import { toComposeProjectName } from "./compose-project-name.js";
import { ownedComposeProjects } from "./demo-reset.js";
import { projectNetworkNames } from "./down-cleanup.js";
const defaultDocker = (args) => execFileSync("docker", args, {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
    windowsHide: true,
});
function lines(text) {
    return text
        .split(/\r?\n/)
        .map((line) => line.trim())
        .filter(Boolean);
}
/**
 * The name in `names` that owns `candidate` when Flisk joins the name and a suffix with `separator`, or undefined. The
 * longest match wins, so project `shop` with a stack `admin` does not claim `shop_admin_web` while `shop-admin` is known.
 */
export function ownerOf(candidate, separator, names, transform = (name) => name) {
    let best;
    for (const name of names) {
        const prefix = transform(name) + separator;
        if (candidate.startsWith(prefix) &&
            (!best || transform(best).length < transform(name).length)) {
            best = name;
        }
    }
    return best;
}
/** The golden layer keys (GOLDEN_LAYERS in golden_image_constants.star) and the retired l3-migrator. */
const GOLDEN_LAYERS = new Set([
    "l1",
    "l2",
    "l3-backend",
    "l3-frontend",
    "l3-migrator",
    "l4-backend",
    "l4-backend-node",
    "l4-frontend",
    "l4-migrator",
]);
/**
 * Lists the Docker objects of project `name`, by the exact names the engine gives them: Compose projects
 * `<name>-<infra>` and `<name>-<stack>-autogenerated` (containers and volumes), networks `<name_underscored>_<suffix>`,
 * golden images `<name>-<layer>` and service images `<name_underscored>_<stack>_<service>`. A name prefix is not enough:
 * project `shop` must not claim the database of `shop-admin`, which may never have been recorded. A volume without a
 * Compose project label is never claimed.
 */
export function listProjectArtifacts(name, identity, docker = defaultDocker) {
    const composeProjects = ownedComposeProjects(name, [...identity.stacks]);
    const names = [...new Set([name, ...(identity.knownNames ?? [])])];
    const underscored = toComposeProjectName(name);
    const isServiceImage = (repository) => identity.stacks.some((stack) => {
        const lower = stack.toLowerCase();
        return (repository.startsWith(`${underscored}_${lower}_`) ||
            repository === `${underscored}_${lower}-db-migrator`);
    }) && ownerOf(repository, "_", names, toComposeProjectName) === name;
    const read = (args) => {
        try {
            return lines(docker(args));
        }
        catch {
            return [];
        }
    };
    const containers = read([
        "ps",
        "-a",
        "--format",
        '{{.Names}}\t{{.Label "com.docker.compose.project"}}',
    ])
        .map((line) => line.split("\t"))
        .filter(([, composeProject = ""]) => composeProjects.has(composeProject))
        .map(([container = ""]) => container);
    const volumes = read([
        "volume",
        "ls",
        "--format",
        '{{.Name}}\t{{.Label "com.docker.compose.project"}}',
    ])
        .map((line) => line.split("\t"))
        .filter(([, composeProject = ""]) => composeProjects.has(composeProject))
        .map(([volume = ""]) => volume);
    const existingNetworks = new Set(read(["network", "ls", "--format", "{{.Name}}"]));
    const networks = projectNetworkNames(name).filter((network) => existingNetworks.has(network));
    const images = read(["images", "--format", "{{.Repository}}:{{.Tag}}"]).filter((ref) => {
        const [repository = "", tag = ""] = ref.split(/:(?=[^:]*$)/);
        if (!repository || repository === "<none>" || tag === "<none>")
            return false;
        if (repository.startsWith(`${name}-`) && GOLDEN_LAYERS.has(repository.slice(name.length + 1))) {
            return true;
        }
        return isServiceImage(repository);
    });
    return { containers, volumes, networks, images };
}
function firstLine(err) {
    const stderr = String(err.stderr ?? err).trim();
    return stderr.split(/\r?\n/)[0] ?? "";
}
/**
 * Removes what {@link listProjectArtifacts} found: containers first (they hold the volumes and networks), then
 * volumes, networks and images. Images are untagged without `--force`, so an image another container runs stays.
 */
export function removeProjectArtifacts(artifacts, docker = defaultDocker) {
    const result = {
        removed: { containers: [], volumes: [], networks: [], images: [] },
        kept: [],
    };
    const steps = [
        ["containers", (name) => ["rm", "-f", name]],
        ["volumes", (name) => ["volume", "rm", name]],
        ["networks", (name) => ["network", "rm", name]],
        ["images", (name) => ["image", "rm", name]],
    ];
    for (const [kind, args] of steps) {
        for (const name of artifacts[kind]) {
            try {
                docker(args(name));
                result.removed[kind].push(name);
            }
            catch (err) {
                result.kept.push({ kind, name, reason: firstLine(err) });
            }
        }
    }
    return result;
}
export function countArtifacts(artifacts) {
    return (artifacts.containers.length +
        artifacts.volumes.length +
        artifacts.networks.length +
        artifacts.images.length);
}
